// e2e/specs/axe-route-walk.spec.ts — #106 (F-046): an accessibility strategy proportional to the
// registered screen count, not to how many hand-authored specs happen to call `expectNoAxeViolations`.
//
// Before this file, the repo's only automated a11y coverage was the axe call inside each of the 16
// critical-workflow specs — one scan per WORKFLOW, not per SCREEN, against a 301-screen registry
// (`audit/ui-parity/ui-parity.json`, generated by `bun run ui:parity` and kept fresh by the
// `arch:ui-parity` fitness gate). This spec is the cheap, structural half #106's acceptance criteria
// ask for: walk every STATICALLY-routable `web`-app screen (no `:param` segments — a dynamic route
// needs a real seeded resource id per screen and is out of this spec's scope, same as every other
// e2e spec that opens one by navigating from a list rather than guessing a path) as the admin persona
// (816 permission keys — the broadest RBAC reach any seeded account has) and run a WCAG 2A/AA scan on
// each. It catches the STRUCTURAL class of defect (missing labels, landmark/heading order, contrast) —
// keyboard operation, focus order, zoom, and screen-reader behavior on the high-risk clinical forms are
// NOT automatable this way and stay a scheduled, manual review (#106's own acceptance criteria say so).
//
// SCOPE, explicitly: `web` only. `admin` (34 screens) and `portal` (13 screens) run on their own Vite
// dev servers (ports 5175/5174) that `bun run dev` does not start and this suite's single `baseURL`
// does not reach — walking them needs their own Playwright config, not a screen filter here. Pre-auth
// screens (`permission: "(none)"` — sign-in, forgot/reset password, the MFA challenge) are excluded:
// this spec signs in once and stays signed in, and `auth.spec.ts` already scans the sign-in page in
// its own unauthenticated context. `bun run scripts/report-e2e-axe-coverage.ts` is the measured
// half — the audit/ report naming exactly which registered screens this spec does and does not reach.
import { readFileSync } from "node:fs";
import { join } from "node:path";
import AxeBuilder from "@axe-core/playwright";
import { expect, test } from "@playwright/test";
import { ADMIN_ACCOUNT } from "../fixtures/credentials";
import { signInAs } from "../fixtures/helpers";

interface RegisteredScreen {
  readonly app: string;
  readonly module: string;
  readonly id: string;
  readonly path: string;
  readonly permission: string;
}

/** The `web`-app, statically-routable, post-auth screens — see the header for what and why. */
function staticWebScreens(): RegisteredScreen[] {
  const jsonPath = join(import.meta.dirname, "..", "..", "audit", "ui-parity", "ui-parity.json");
  const data = JSON.parse(readFileSync(jsonPath, "utf8")) as { screens: RegisteredScreen[] };
  return data.screens
    .filter((s) => s.app === "web")
    .filter((s) => !s.path.includes(":"))
    .filter((s) => s.permission !== "(none)")
    .sort((a, b) => a.path.localeCompare(b.path));
}

test.describe("Accessibility — route walk (#106, F-046)", () => {
  test("every static registered web screen scans clean for WCAG 2A/AA (admin persona)", async ({
    page,
  }) => {
    const screens = staticWebScreens();
    expect(screens.length).toBeGreaterThan(100); // the registry itself going empty is its own defect
    test.setTimeout(Math.max(120_000, screens.length * 4_000));

    await signInAs(page, ADMIN_ACCOUNT());

    const failures: string[] = [];
    for (const screen of screens) {
      try {
        await page.goto(screen.path, { waitUntil: "domcontentloaded" });
        await page.waitForLoadState("networkidle").catch(() => {});
      } catch (err) {
        failures.push(`${screen.id} (${screen.path}): navigation failed — ${String(err)}`);
        continue;
      }
      const rootEmpty = await page
        .locator("#root")
        .evaluate((el) => el.childElementCount === 0)
        .catch(() => true);
      if (rootEmpty) {
        failures.push(`${screen.id} (${screen.path}): #root rendered empty`);
        continue;
      }
      const results = await new AxeBuilder({ page }).withTags(["wcag2a", "wcag2aa"]).analyze();
      for (const v of results.violations) {
        const targets = v.nodes.map((n) => n.target.join(" ")).join(", ");
        failures.push(`${screen.id} (${screen.path}): ${v.id} (${v.impact}) — ${targets}`);
      }
    }

    expect(
      failures,
      `${failures.length} issue(s) across ${screens.length} screen(s):\n${failures.join("\n")}`,
    ).toEqual([]);
  });
});
